fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len()); // Preallocate memory for the result vector

    for &c in str1.iter() {
        if c >= 'a' && c <= 'z' {
            result.push((c as u8 - b'a' + b'A') as char); // Convert to uppercase
        } else {
            result.push(c); // Keep the character unchanged
        }
    }

    result
}